//! Parsing of human-friendly byte sizes, e.g. "1MB", "4K", "1.5GiB".
//!
//! The accepted grammar is a (floating point) number, optional
//! whitespace and an optional unit suffix.  Units are binary (1K ==
//! 1024).  The unit may be written as a single letter ("K"), with a
//! trailing "B" ("KB") or in IEC form ("KiB"), case-insensitively.

use std::fmt;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SizeError {
    Invalid,
    TooLarge,
}

impl fmt::Display for SizeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            SizeError::Invalid => write!(f, "could not interpret string as byte size"),
            SizeError::TooLarge => write!(f, "byte size too large"),
        }
    }
}

impl std::error::Error for SizeError {}

/// Returns the binary exponent (power of 1024) for a unit letter.
fn unit_power(c: char) -> Option<u32> {
    match c.to_ascii_lowercase() {
        'b' => Some(0),
        'k' => Some(1),
        'm' => Some(2),
        'g' => Some(3),
        't' => Some(4),
        'p' => Some(5),
        'e' => Some(6),
        _ => None,
    }
}

/// Validate a unit suffix. The first character selects the unit; the
/// remainder may consist of repetitions of the unit letter, optionally
/// each followed by "b" or "ib".
fn parse_suffix(suffix: &str) -> Result<u32, SizeError> {
    let lower = suffix.to_ascii_lowercase();
    let mut chars = lower.chars().peekable();
    let unit = match chars.next() {
        None => return Ok(0),
        Some(c) => c,
    };
    let power = unit_power(unit).ok_or(SizeError::Invalid)?;
    // Consume optional "ib"/"b" after a unit letter.
    let mut eat_bytes_marker = |chars: &mut std::iter::Peekable<std::str::Chars>| -> Result<(), SizeError> {
        match chars.peek() {
            Some('i') => {
                chars.next();
                match chars.next() {
                    Some('b') => Ok(()),
                    _ => Err(SizeError::Invalid),
                }
            }
            Some('b') if unit != 'b' => {
                chars.next();
                Ok(())
            }
            _ => Ok(()),
        }
    };
    eat_bytes_marker(&mut chars)?;
    while let Some(c) = chars.next() {
        if c != unit {
            return Err(SizeError::Invalid);
        }
        eat_bytes_marker(&mut chars)?;
    }
    Ok(power)
}

/// Parse a size string into a number of bytes.
pub fn parse_size(value: &str) -> Result<u64, SizeError> {
    let value = value.trim();

    // Examine the leading character; a sign is only allowed if it is a
    // plus. Note that this deliberately indexes the string, so an
    // empty string will panic, as will a leading multi-byte char.
    let lead = &value[..1];
    if lead == "-" {
        return Err(SizeError::Invalid);
    }

    // Plain integers are taken as-is.
    if let Ok(v) = value.parse::<u64>() {
        return Ok(v);
    }

    // Split off the trailing alphabetic suffix.
    let split = value
        .char_indices()
        .rev()
        .take_while(|(_, c)| c.is_alphabetic())
        .last()
        .map(|(i, _)| i)
        .unwrap_or(value.len());
    let (number, suffix) = value.split_at(split);
    let number = number.trim();

    let num: f64 = number.parse().map_err(|_| SizeError::Invalid)?;
    if num.is_sign_negative() {
        return Err(SizeError::Invalid);
    }

    if suffix.is_empty() {
        // No unit; fractional values make no sense for bytes.
        if num.fract() > 0.0 {
            return Err(SizeError::Invalid);
        }
        return Ok(num as u64);
    }

    let power = parse_suffix(suffix)?;
    let scale: u64 = 1u64 << (10 * power);

    let whole = num as u64;
    if whole == 0 {
        return Ok(0);
    }
    let frac = num % (whole as f64);
    let base = whole.checked_mul(scale).ok_or(SizeError::TooLarge)?;
    let extra = (frac * scale as f64) as u64;
    base.checked_add(extra).ok_or(SizeError::TooLarge)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basics() {
        assert_eq!(parse_size("1"), Ok(1));
        assert_eq!(parse_size("1k"), Ok(1024));
        assert_eq!(parse_size("1KiB"), Ok(1024));
        assert_eq!(parse_size("1.5K"), Ok(1536));
        assert_eq!(parse_size("1e3"), Ok(1000));
        assert_eq!(parse_size("1e3k"), Ok(1024000));
        assert_eq!(parse_size("0.5K"), Ok(0));
        assert_eq!(parse_size("1.5"), Err(SizeError::Invalid));
        assert_eq!(parse_size("1KK"), Ok(1024));
        assert_eq!(parse_size("1KBB"), Err(SizeError::Invalid));
        assert_eq!(parse_size("1Ki"), Err(SizeError::Invalid));
        assert_eq!(parse_size("16E"), Err(SizeError::TooLarge));
        assert_eq!(parse_size("-1"), Err(SizeError::Invalid));
    }
}
EOF
echo done"}

