use std::time::{SystemTime, UNIX_EPOCH};

use log::{Level, LevelFilter, Log, Metadata, Record};

struct TermLogger {
    level: LevelFilter,
}

fn timestamp() -> String {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    let secs = now % 86400;
    format!("{:02}:{:02}:{:02}", secs / 3600, (secs / 60) % 60, secs % 60)
}

fn thread_id() -> String {
    let id = format!("{:?}", thread::current().id());
    id.trim_start_matches("ThreadId(")
        .trim_end_matches(')')
        .to_string()
}

impl TermLogger {
    fn format(&self, record: &Record<'_>) -> String {
        let level = record.level();
        let mut line = format!("{} [{}] ", timestamp(), level);
        if level >= Level::Debug {
            line.push_str(&format!("({}) ", thread_id()));
            line.push_str(&format!("{}: ", record.target()));
        }
        if level >= Level::Trace {
            let file = record.file().unwrap_or("<unknown>");
            match record.line() {
                Some(l) => line.push_str(&format!("[{}:{}] ", file, l)),
                None => line.push_str(&format!("[{}:<unknown>] ", file)),
            }
        }
        line.push_str(&format!("{}\n", record.args()));
        line
    }
}

impl Log for TermLogger {
    fn enabled(&self, metadata: &Metadata<'_>) -> bool {
        metadata.level() <= self.level
    }

    fn log(&self, record: &Record<'_>) {
        if !self.enabled(record.metadata()) {
            return;
        }
        let line = self.format(record);
        if record.level() == Level::Error {
            let stderr = io::stderr();
            let mut lock = stderr.lock();
            let _ = lock.write_all(line.as_bytes());
            let _ = lock.flush();
        } else {
            let stdout = io::stdout();
            let mut lock = stdout.lock();
            let _ = lock.write_all(line.as_bytes());
            let _ = lock.flush();
        }
    }

    fn flush(&self) {
        let _ = io::stdout().flush();
        let _ = io::stderr().flush();
    }
}

/// Install the logger with the given maximum level.
pub fn init(level: LevelFilter) {
    let logger = Box::new(TermLogger { level });
    if log::set_boxed_logger(logger).is_ok() {
        log::set_max_level(level);
    }
}
