}

const DRAW_MAX_BURST: u8 = 20;

impl DrawLimiter {
    fn new(rate_hz: u64) -> Self {
        DrawLimiter {
            interval_ms: 1000 / rate_hz,
            capacity: DRAW_MAX_BURST,
            prev: Instant::now(),
        }
    }

    fn allow(&mut self, now: Instant) -> bool {
        if now < self.prev {
            return false;
        }
        let elapsed = now - self.prev;
        let interval = Duration::from_millis(self.interval_ms);
        if self.capacity == 0 && elapsed < interval {
            return false;
        }
        let new = elapsed.as_millis() as u64 / self.interval_ms;
        let remainder = elapsed.as_nanos() as u64 % (self.interval_ms * 1_000_000);
        let cap = (self.capacity as u64 + new).saturating_sub(1);
        self.capacity = cap.min(DRAW_MAX_BURST as u64) as u8;
        self.prev = now - Duration::from_nanos(remainder);
        true
    }
}

/// Limiter for position-update ticks (estimator + redraw requests).
struct TickLimiter {
    capacity: u8,
    prev_ns: u64,
    start: Instant,
}

const TICK_INTERVAL_NS: u64 = 1_000_000;
const TICK_MAX_BURST: u8 = 10;

impl TickLimiter {
    fn new() -> Self {
        TickLimiter {
            capacity: TICK_MAX_BURST,
            prev_ns: 0,
            start: Instant::now(),
        }
    }

    fn allow(&mut self, now: Instant) -> bool {
        if now < self.start {
            return false;
        }
        let total = (now - self.start).as_nanos() as u64;
        let elapsed = total.saturating_sub(self.prev_ns);
        let new = elapsed / TICK_INTERVAL_NS;
        if new == 0 && self.capacity == 0 {
            return false;
