        let cap = (self.capacity as u64 + new).min(TICK_MAX_BURST as u64);
        self.capacity = (cap - 1) as u8;
        self.prev_ns = self.prev_ns + new * TICK_INTERVAL_NS;
        if self.prev_ns > total {
            self.prev_ns = total;
        }
        true
    }

