        self.prev_ns = now.saturating_duration_since(self.start).as_nanos() as u64;
    }
}

// ---------------------------------------------------------------------
// Rate estimation
// ---------------------------------------------------------------------

fn estimator_weight(age: f64) -> f64 {
    const EXPONENTIAL_WEIGHTING_SECONDS: f64 = 15.0;
    0.1_f64.powf(age / EXPONENTIAL_WEIGHTING_SECONDS)
}

struct Estimator {
    smoothed: f64,
    double_smoothed: f64,
    prev_steps: u64,
    prev_time: Instant,
    start_time: Instant,
}

impl Estimator {
    fn new(now: Instant) -> Self {
        Estimator {
            smoothed: 0.0,
            double_smoothed: 0.0,
            prev_steps: 0,
            prev_time: now,
            start_time: now,
        }
    }

    fn record(&mut self, new_steps: u64, now: Instant) {
        if new_steps <= self.prev_steps || now <= self.prev_time {
            if new_steps < self.prev_steps {
                self.prev_steps = new_steps;
                self.reset(now);
            }
            return;
        }
        let delta_steps = new_steps - self.prev_steps;
        let delta_t = (now - self.prev_time).as_secs_f64();
        let new_rate = delta_steps as f64 / delta_t;

        let weight = estimator_weight(delta_t);
        self.smoothed = self.smoothed * weight + new_rate * (1.0 - weight);

        let delta_t_start = (now - self.start_time).as_secs_f64();
        let total_weight = 1.0 - estimator_weight(delta_t_start);
        let normalized = self.smoothed / total_weight;

        self.double_smoothed = self.double_smoothed * weight + normalized * (1.0 - weight);

        self.prev_steps = new_steps;
        self.prev_time = now;
    }

    fn reset(&mut self, now: Instant) {
        self.smoothed = 0.0;
        self.double_smoothed = 0.0;
        self.prev_time = now;
        self.start_time = now;
    }

    fn steps_per_second(&self, now: Instant) -> f64 {
        let delta_t_start = (now - self.start_time).as_secs_f64();
        let total_weight = 1.0 - estimator_weight(delta_t_start);
        self.double_smoothed / total_weight
    }
}

// ---------------------------------------------------------------------
// Terminal output
// ---------------------------------------------------------------------

struct TermTarget {
    last_line_count: usize,
    limiter: DrawLimiter,
}

impl TermTarget {
    fn size(&self) -> (usize, usize) {
        match term::size_of(libc::STDERR_FILENO) {
            Some((rows, cols)) => (rows as usize, cols as usize),
            None => (24, 80),
        }
    }

    fn draw(&mut self, lines: &[String]) -> io::Result<()> {
        let mut out = String::new();

        // Clear the previously drawn lines. The cursor sits at the end of
        // the last line, so move up, clear each line and move back.
        let n = self.last_line_count;
        move_cursor_up(&mut out, n.saturating_sub(1));
        for i in 0..n {
            clear_line(&mut out);
            if i + 1 != n {
                move_cursor_down(&mut out, 1);
            }
        }
        move_cursor_up(&mut out, n.saturating_sub(1));

        let (term_height, term_width) = self.size();
        let len = lines.len();
        let mut real_len = 0usize;
        let mut last_line_filler = 0usize;
        for (idx, line) in lines.iter().enumerate() {
            let line_width = line.chars().count();
            let diff = if line.is_empty() {
                1
            } else {
                let wrapped = (line_width as f64 / term_width as f64).ceil() as usize;
                wrapped.max(1)
            };
            if real_len + diff > term_height {
                break;
            }
            real_len += diff;
            if idx != 0 {
                out.push('\n');
            }
            out.push_str(line);
            if idx + 1 == len {
                last_line_filler = (diff * term_width).saturating_sub(line_width);
            }
        }
        out.extend(std::iter::repeat(' ').take(last_line_filler));

        let stderr = io::stderr();
        let mut lock = stderr.lock();
        lock.write_all(out.as_bytes())?;
        lock.flush()?;
        self.last_line_count = real_len;
        Ok(())
    }
}

fn move_cursor_up(out: &mut String, n: usize) {
    if n > 0 {
        out.push_str(&format!("\x1b[{}A", n));
    }
}

fn move_cursor_down(out: &mut String, n: usize) {
    if n > 0 {
        out.push_str(&format!("\x1b[{}B", n));
    }
}

fn clear_line(out: &mut String) {
    out.push_str("\r\x1b[2K");
}

// ---------------------------------------------------------------------
// Layout
// ---------------------------------------------------------------------

/// Layout of the bar; wide terminals get everything on one line,
/// narrower ones get the bar on its own line above the statistics.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Layout {
    SingleLine,
    TwoLine,
}

impl Layout {
    /// Pick a layout for the current terminal.
    pub fn detect() -> Layout {
        match term::terminal_size() {
            Some((cols, _rows)) if cols < 160 => Layout::TwoLine,
            _ => Layout::SingleLine,
        }
    }
}

fn format_bar(fract: f32, width: usize) -> String {
    let fill = fract * width as f32;
    let entirely_filled = fill as usize;
    let head = usize::from(fill > 0.0 && entirely_filled < width);
    let bg = width.saturating_sub(entirely_filled).saturating_sub(head);
    let mut bar = String::with_capacity(width);
    bar.extend(std::iter::repeat('#').take(entirely_filled));
    if head == 1 {
        bar.push('>');
    }
    bar.extend(std::iter::repeat('-').take(bg));
    bar
}

// ---------------------------------------------------------------------
// The progress bar
// ---------------------------------------------------------------------

pub struct ProgressBar {
    pos: u64,
    len: u64,
    started: Instant,
    finished: bool,
    cleared: bool,
    tick_limiter: TickLimiter,
    est: Estimator,
    layout: Layout,
    target: Option<TermTarget>,
}

impl ProgressBar {
    /// Create a bar with zero length. If `visible` is false, or stderr is
    /// not a terminal, nothing is ever drawn.
    pub fn new(visible: bool, layout: Layout) -> ProgressBar {
        let now = Instant::now();
        let target = if visible && term::is_terminal(libc::STDERR_FILENO) {
            Some(TermTarget {
                last_line_count: 0,
                limiter: DrawLimiter::new(20),
            })
        } else {
            None
        };
        ProgressBar {
            pos: 0,
            len: 0,
            started: now,
            finished: false,
            cleared: false,
            tick_limiter: TickLimiter::new(),
            est: Estimator::new(now),
            layout,
            target,
        }
    }

    pub fn inc(&mut self, delta: u64) {
        self.pos = self.pos.saturating_add(delta);
        let now = Instant::now();
        if self.tick_limiter.allow(now) {
            self.update_estimate_and_draw(now);
        }
    }

    pub fn inc_length(&mut self, delta: u64) {
        self.len = self.len.saturating_add(delta);
        self.update_estimate_and_draw(Instant::now());
    }

    /// Mark the bar complete, leaving it on the terminal.
    pub fn finish(&mut self) {
        if self.finished {
            return;
        }
        self.finished = true;
        self.pos = self.len;
        self.draw(true, Instant::now());
    }

    /// Mark the bar complete and remove it from the terminal.
    pub fn finish_and_clear(&mut self) {
        if self.finished {
            return;
        }
        self.finished = true;
        self.cleared = true;
        self.draw(true, Instant::now());
    }

    fn update_estimate_and_draw(&mut self, now: Instant) {
        self.est.record(self.pos, now);
        self.draw(false, now);
    }

    fn fraction(&self) -> f32 {
        let pct = match (self.pos, self.len) {
            (_, 0) => 1.0,
            (0, _) => 0.0,
            (pos, len) => pos as f32 / len as f32,
        };
        pct.clamp(0.0, 1.0)
    }

    fn eta(&self, now: Instant) -> Duration {
        if self.finished {
            return Duration::ZERO;
        }
        let sps = self.est.steps_per_second(now);
        if sps == 0.0 {
            return Duration::ZERO;
        }
        let secs = self.len.saturating_sub(self.pos) as f64 / sps;
        if !secs.is_finite() || secs < 0.0 {
            return Duration::ZERO;
        }
        Duration::try_from_secs_f64(secs).unwrap_or(Duration::MAX)
    }

    fn per_sec(&self, now: Instant) -> f64 {
        if self.finished {
            let elapsed = now.saturating_duration_since(self.started).as_secs_f64();
            if elapsed > 0.0 {
                self.pos as f64 / elapsed
            } else {
                0.0
            }
        } else {
            self.est.steps_per_second(now)
        }
    }

    fn stats(&self, now: Instant) -> String {
        let pct = format!("{:.0}", self.fraction() * 100f32);
        let rate = format!("{}/s", human_bytes(self.per_sec(now) as u64));
        format!(
            "{} / {} | {}% | {} | {} remaining",
            pad(&human_bytes(self.pos), 11, Align::Right),
            pad(&human_bytes(self.len), 11, Align::Left),
            pad(&pct, 3, Align::Right),
            pad(&rate, 13, Align::Center),
            formatted_duration(self.eta(now)),
        )
    }

    fn render(&self, width: usize, now: Instant) -> Vec<String> {
        let stats = self.stats(now);
        match self.layout {
            Layout::SingleLine => {
                let rest = format!("[] {}", stats);
                let bar_width = width.saturating_sub(rest.chars().count());
                vec![format!("[{}] {}", format_bar(self.fraction(), bar_width), stats)]
            }
            Layout::TwoLine => {
                let bar_width = width.saturating_sub(2);
                vec![format!("[{}]", format_bar(self.fraction(), bar_width)), stats]
            }
        }
    }

    fn draw(&mut self, force: bool, now: Instant) {
        let force = force || self.finished;
        let lines = {
            let target = match self.target.as_mut() {
                Some(t) => t,
                None => return,
            };
            if !(force || target.limiter.allow(now)) {
                return;
            }
            if self.cleared {
                Vec::new()
            } else {
                let (_, width) = target.size();
                self.render(width, now)
            }
        };
        if let Some(target) = self.target.as_mut() {
            let _ = target.draw(&lines);
        }
    }
}

impl Drop for ProgressBar {
    fn drop(&mut self) {
        if !self.finished {
            self.finish_and_clear();
        }
    }
}
