//! Minimal terminal queries.

use std::mem::MaybeUninit;

pub fn is_terminal(fd: i32) -> bool {
    unsafe { libc::isatty(fd) == 1 }
}

/// Returns (rows, cols) for the terminal attached to `fd`, if any.
pub fn size_of(fd: i32) -> Option<(u16, u16)> {
    if !is_terminal(fd) {
        return None;
    }
    let mut ws = MaybeUninit::<libc::winsize>::zeroed();
    let rc = unsafe { libc::ioctl(fd, libc::TIOCGWINSZ, ws.as_mut_ptr()) };
    if rc != 0 {
        return None;
    }
    let ws = unsafe { ws.assume_init() };
    if ws.ws_row > 0 && ws.ws_col > 0 {
        Some((ws.ws_row, ws.ws_col))
    } else {
        None
    }
}

/// Returns (cols, rows) of the controlling terminal, trying stdout,
/// stderr and stdin in turn.
pub fn terminal_size() -> Option<(u16, u16)> {
    for fd in [libc::STDOUT_FILENO, libc::STDERR_FILENO, libc::STDIN_FILENO] {
        if let Some((rows, cols)) = size_of(fd) {
            return Some((cols, rows));
        }
    }
    None
}
