//! Low-level filesystem helpers: accelerated copies, reflinks, sparse
//! file handling and metadata copying.

use std::ffi::{CStr, CString, OsStr, OsString};
use std::fs::{self, File};
use std::io;
use std::ops::Range;
use std::os::unix::ffi::{OsStrExt, OsStringExt};
use std::os::unix::fs::{MetadataExt, PermissionsExt};
use std::os::unix::io::AsRawFd;
use std::path::Path;

use log::{debug, warn};

use crate::errors::{Result, XcpError};
use crate::options::Opts;

const LOG_TARGET: &str = "libfs::common";

fn cvt(rc: i64) -> io::Result<i64> {
    if rc < 0 {
        Err(io::Error::last_os_error())
    } else {
        Ok(rc)
    }
}

fn fstat(fd: &File) -> io::Result<libc::stat> {
    let mut st = std::mem::MaybeUninit::<libc::stat>::zeroed();
    let rc = unsafe { libc::fstat(fd.as_raw_fd(), st.as_mut_ptr()) };
    cvt(rc as i64)?;
    Ok(unsafe { st.assume_init() })
}

/// Copy `bytes` from the current offset of `infd` to the current offset
/// of `outfd` using `copy_file_range`.
pub fn copy_file_bytes(infd: &File, outfd: &File, bytes: u64) -> Result<u64> {
    let rc = unsafe {
        libc::syscall(
            libc::SYS_copy_file_range,
            infd.as_raw_fd(),
            std::ptr::null_mut::<libc::loff_t>(),
            outfd.as_raw_fd(),
            std::ptr::null_mut::<libc::loff_t>(),
            bytes as usize,
            0u32,
        )
    };
    Ok(cvt(rc as i64)? as u64)
}

/// Copy `bytes` from `infd` to `outfd`, both at offset `off`.
pub fn copy_file_offset(infd: &File, outfd: &File, bytes: u64, off: u64) -> Result<u64> {
    let mut in_off = off as libc::loff_t;
    let mut out_off = off as libc::loff_t;
    let rc = unsafe {
        libc::syscall(
            libc::SYS_copy_file_range,
            infd.as_raw_fd(),
            &mut in_off as *mut libc::loff_t,
            outfd.as_raw_fd(),
            &mut out_off as *mut libc::loff_t,
            bytes as usize,
            0u32,
        )
    };
    Ok(cvt(rc as i64)? as u64)
}

const FICLONE: libc::c_ulong = 0x4004_9409;

/// Attempt to reflink (clone) `infd` to `outfd`. Returns Ok(true) on
/// success, Ok(false) if the filesystem refused.
pub fn reflink(infd: &File, outfd: &File) -> Result<bool> {
    let rc = unsafe { libc::ioctl(outfd.as_raw_fd(), FICLONE, infd.as_raw_fd()) };
    if rc == 0 {
        Ok(true)
    } else {
        let err = io::Error::last_os_error();
        match err.raw_os_error() {
            Some(libc::EOPNOTSUPP)
            | Some(libc::ENOTTY)
            | Some(libc::EINVAL)
            | Some(libc::EXDEV)
            | Some(libc::EBADF)
            | Some(libc::EPERM)
            | Some(libc::ENOSYS)
            | Some(libc::EISDIR)
            | Some(libc::ETXTBSY) => Ok(false),
            _ => Err(err.into()),
        }
    }
}

/// Guess whether a file has holes by comparing allocated blocks to size.
pub fn probably_sparse(fd: &File) -> Result<bool> {
    let st = fstat(fd)?;
    Ok((st.st_blocks as u64) * 512 < st.st_size as u64)
}

fn lseek(fd: &File, off: i64, whence: i32) -> io::Result<Option<u64>> {
    let rc = unsafe { libc::lseek(fd.as_raw_fd(), off, whence) };
    if rc < 0 {
        let err = io::Error::last_os_error();
        if err.raw_os_error() == Some(libc::ENXIO) {
            return Ok(None);
        }
        return Err(err);
    }
    Ok(Some(rc as u64))
}

/// Map the data extents of a file using SEEK_DATA/SEEK_HOLE.
pub fn map_extents(fd: &File) -> Result<Vec<Range<u64>>> {
    let len = fstat(fd)?.st_size as u64;
    let mut extents = Vec::new();
    let mut pos = 0u64;
    while pos < len {
        let start = match lseek(fd, pos as i64, libc::SEEK_DATA)? {
            Some(s) => s,
            None => break,
        };
        let end = match lseek(fd, start as i64, libc::SEEK_HOLE)? {
            Some(e) => e,
            None => len,
        };
        if end <= start {
            break;
        }
        extents.push(start..end);
        pos = end;
    }
    Ok(extents)
}

pub fn allocate_file(fd: &File, len: u64) -> Result<()> {
    fd.set_len(len)?;
    Ok(())
}

pub fn sync(fd: &File) -> Result<()> {
    fd.sync_all()?;
    Ok(())
}

fn list_xattrs(fd: &File) -> io::Result<Vec<OsString>> {
    let fd = fd.as_raw_fd();
    loop {
        let size = cvt(unsafe { libc::flistxattr(fd, std::ptr::null_mut(), 0) } as i64)?;
        if size == 0 {
            return Ok(Vec::new());
        }
        let mut buf = vec![0u8; size as usize];
        let rc = unsafe { libc::flistxattr(fd, buf.as_mut_ptr() as *mut libc::c_char, buf.len()) };
        if rc < 0 {
            let err = io::Error::last_os_error();
            if err.raw_os_error() == Some(libc::ERANGE) {
                continue;
            }
            return Err(err);
        }
        buf.truncate(rc as usize);
        let names = buf
            .split(|b| *b == 0)
            .filter(|s| !s.is_empty())
            .map(|s| OsString::from_vec(s.to_vec()))
            .collect();
        return Ok(names);
    }
}

fn get_xattr(fd: &File, name: &CStr) -> io::Result<Vec<u8>> {
    let fd = fd.as_raw_fd();
    loop {
        let size = cvt(unsafe { libc::fgetxattr(fd, name.as_ptr(), std::ptr::null_mut(), 0) } as i64)?;
        let mut buf = vec![0u8; size as usize];
        let rc = unsafe { libc::fgetxattr(fd, name.as_ptr(), buf.as_mut_ptr() as *mut libc::c_void, buf.len()) };
        if rc < 0 {
            let err = io::Error::last_os_error();
            if err.raw_os_error() == Some(libc::ERANGE) {
                continue;
            }
            return Err(err);
        }
        buf.truncate(rc as usize);
        return Ok(buf);
    }
}

fn set_xattr(fd: &File, name: &CStr, value: &[u8]) -> io::Result<()> {
    let rc = unsafe {
        libc::fsetxattr(
            fd.as_raw_fd(),
            name.as_ptr(),
            value.as_ptr() as *const libc::c_void,
            value.len(),
            0,
        )
    };
    cvt(rc as i64)?;
    Ok(())
}

pub fn copy_xattr(infd: &File, outfd: &File) -> Result<()> {
    debug!(target: LOG_TARGET, "Starting xattr copy...");
    for name in list_xattrs(infd)? {
        debug!(target: LOG_TARGET, "Copy xattr {:?}", name);
        let cname = CString::new(name.as_bytes())
            .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "invalid xattr name"))?;
        let value = get_xattr(infd, &cname)?;
        set_xattr(outfd, &cname, &value)?;
    }
    Ok(())
}

pub fn copy_permissions(infd: &File, outfd: &File) -> Result<()> {
    debug!(target: LOG_TARGET, "Performing permissions copy");
    let perms = infd.metadata()?.permissions();
    outfd.set_permissions(fs::Permissions::from_mode(perms.mode()))?;
    Ok(())
}

pub fn copy_timestamps(infd: &File, outfd: &File) -> Result<()> {
    debug!(target: LOG_TARGET, "Performing timestamp copy");
    let st = fstat(infd)?;
    let times = [
        libc::timespec {
            tv_sec: st.st_atime,
            tv_nsec: st.st_atime_nsec,
        },
        libc::timespec {
            tv_sec: st.st_mtime,
            tv_nsec: st.st_mtime_nsec,
        },
    ];
    let rc = unsafe { libc::futimens(outfd.as_raw_fd(), times.as_ptr()) };
    cvt(rc as i64)?;
    Ok(())
}

pub fn copy_owner(infd: &File, outfd: &File) -> Result<()> {
    let st = fstat(infd)?;
    let rc = unsafe { libc::fchown(outfd.as_raw_fd(), st.st_uid, st.st_gid) };
    cvt(rc as i64)?;
    Ok(())
}

/// Copy all requested file metadata from `infd` to `outfd`.
pub fn copy_metadata(infd: &File, outfd: &File, opts: &Opts) -> Result<()> {
    if !opts.no_perms {
        copy_xattr(infd, outfd)?;
        copy_permissions(infd, outfd)?;
    }
    if !opts.no_timestamps {
        copy_timestamps(infd, outfd)?;
    }
    if opts.ownership && copy_owner(infd, outfd).is_err() {
        warn!("Failed to copy file ownership: {:?}", infd);
    }
    Ok(())
}

/// Recreate a special file (fifo, socket, device) at `dest` with the
/// same mode and device numbers as `src`.
pub fn copy_node(src: &Path, dest: &Path) -> Result<()> {
    let meta = fs::symlink_metadata(src)?;
    if dest.exists() {
        fs::remove_file(dest)?;
    }
    let cdest = CString::new(dest.as_os_str().as_bytes())
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "invalid path"))?;
    let rc = unsafe { libc::mknod(cdest.as_ptr(), meta.mode() as libc::mode_t, meta.rdev() as libc::dev_t) };
    cvt(rc as i64)?;
    Ok(())
}

/// Create a symlink; an existing destination is left untouched.
pub fn symlink(target: &Path, dest: &Path) -> Result<()> {
    match std::os::unix::fs::symlink(target, dest) {
        Ok(()) => Ok(()),
        Err(e) if e.kind() == io::ErrorKind::AlreadyExists => Ok(()),
        Err(e) => Err(e.into()),
    }
}

/// Helper to make an OsStr from bytes for name matching.
pub fn os_str(bytes: &[u8]) -> &OsStr {
    OsStr::from_bytes(bytes)
}

#[allow(dead_code)]
pub fn unsupported() -> XcpError {
    XcpError::UnsupportedOperation
}
EOF
