use std::fs::{self, File};
use std::path::{Path, PathBuf};

use crossbeam_channel::Sender;
use ignore::gitignore::Gitignore;
use log::{debug, error, info};
use walkdir::{DirEntry, WalkDir};

use crate::errors::{Result, XcpError};
use crate::fsops;
use crate::options::{Backup, Opts, Reflink};

const LOG_TARGET: &str = "libxcp::operations";

/// A unit of work handed from the tree walker to a copy driver.
#[derive(Debug)]
pub enum Operation {
    Copy(PathBuf, PathBuf),
    Link(PathBuf, PathBuf),
    Special(PathBuf, PathBuf),
}

/// Progress and error feedback sent to the main thread.
#[derive(Debug)]
pub enum StatusUpdate {
    Copied(u64),
    Size(u64),
    Error(XcpError),
}

pub type StatSender = Sender<StatusUpdate>;

/// Accumulates copied byte counts and emits a status update every time a
/// multiple of the batch size is crossed.
pub struct BatchUpdater {
    sender: StatSender,
    batch_size: u64,
    current: u64,
}

impl BatchUpdater {
    pub fn new(sender: StatSender, batch_size: u64) -> BatchUpdater {
        BatchUpdater {
            sender,
            batch_size,
            current: 0,
        }
    }

    pub fn update(&mut self, bytes: u64) -> Result<()> {
        let curr = self.current;
        let next = curr + bytes;
        if next / self.batch_size > curr / self.batch_size {
            self.sender.send(StatusUpdate::Copied(next))?;
            self.current = 0;
        } else {
            self.current = next;
        }
        Ok(())
    }
}

// ---------------------------------------------------------------------
// Backups
// ---------------------------------------------------------------------

fn existing_backups(path: &Path) -> Result<Vec<u64>> {
    let name = match path.file_name() {
        Some(n) => n.to_string_lossy().into_owned(),
        None => return Ok(Vec::new()),
    };
    let parent = match path.parent() {
        Some(p) if !p.as_os_str().is_empty() => p.to_path_buf(),
        _ => PathBuf::from("."),
    };
    let prefix = format!("{}.~", name);
    let mut found = Vec::new();
    for entry in fs::read_dir(parent)? {
        let entry = entry?;
        let fname = entry.file_name().to_string_lossy().into_owned();
        if let Some(rest) = fname.strip_prefix(&prefix) {
            if let Some(num) = rest.strip_suffix('~') {
                if let Ok(n) = num.parse::<u64>() {
                    found.push(n);
                }
            }
        }
    }
    Ok(found)
}

/// Move an existing destination out of the way if backups are requested.
pub fn backup_file(dest: &Path, opts: &Opts) -> Result<()> {
    if opts.backup == Backup::None || !dest.exists() {
        return Ok(());
    }
    let existing = existing_backups(dest)?;
    let wanted = match opts.backup {
        Backup::Numbered => true,
        Backup::Auto => !existing.is_empty(),
        Backup::None => false,
    };
    if !wanted {
        return Ok(());
    }
    let next = existing.iter().max().map(|n| n + 1).unwrap_or(1);
    let name = dest
        .file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_default();
    let backup = dest.with_file_name(format!("{}.~{}~", name, next));
    info!("Backup: Rename {:?} to {:?}", dest, backup);
    fs::rename(dest, &backup)?;
    Ok(())
}

// ---------------------------------------------------------------------
// File copying
// ---------------------------------------------------------------------

/// Open the source and create the destination (handling backups), and
/// pre-allocate the destination to the source length.
pub fn open_pair(from: &Path, to: &Path, opts: &Opts) -> Result<(File, File, u64)> {
    let infd = File::open(from)?;
    let len = infd.metadata()?.len();
    backup_file(to, opts)?;
    let outfd = File::create(to)?;
    fsops::allocate_file(&outfd, len)?;
    Ok((infd, outfd, len))
}

/// Attempt a reflink according to the configured policy. Returns
/// Ok(true) if the data was cloned and no further copying is needed.
pub fn try_reflink(infd: &File, outfd: &File, opts: &Opts) -> Result<bool> {
    if opts.reflink == Reflink::Never {
        return Ok(false);
    }
    debug!(target: LOG_TARGET, "Attempting reflink from {:?}->{:?}", infd, outfd);
    if fsops::reflink(infd, outfd)? {
        debug!(target: LOG_TARGET, "Reflink {:?} succeeded", outfd);
        return Ok(true);
    }
    if opts.reflink == Reflink::Always {
        return Err(XcpError::ReflinkFailed(format!("{:?}->{:?}", infd, outfd)));
    }
    debug!(target: LOG_TARGET, "Failed to reflink, falling back to copy");
    Ok(false)
}

fn copy_range(
    infd: &File,
    outfd: &File,
    start: u64,
    end: u64,
    opts: &Opts,
    updater: &mut BatchUpdater,
) -> Result<u64> {
    let mut total = 0u64;
    let mut off = start;
    while off < end {
        let chunk = (end - off).min(opts.block_size);
        let n = fsops::copy_file_offset(infd, outfd, chunk, off)?;
        if n == 0 {
            break;
        }
        updater.update(n)?;
        off += n;
        total += n;
    }
    Ok(total)
}

fn copy_sequential(
    infd: &File,
    outfd: &File,
    len: u64,
    opts: &Opts,
    updater: &mut BatchUpdater,
) -> Result<u64> {
    let mut total = 0u64;
    while total < len {
        let chunk = (len - total).min(opts.block_size);
        let n = fsops::copy_file_bytes(infd, outfd, chunk)?;
        if n == 0 {
            break;
        }
        updater.update(n)?;
        total += n;
    }
    Ok(total)
}

/// Copy the data of a file, reflinking where possible and preserving
/// sparse regions.
pub fn copy_file_data(
    infd: &File,
    outfd: &File,
    len: u64,
    opts: &Opts,
    updater: &mut BatchUpdater,
) -> Result<u64> {
    if try_reflink(infd, outfd, opts)? {
        return Ok(len);
    }
    if fsops::probably_sparse(infd)? {
        let mut total = 0u64;
        for extent in fsops::map_extents(infd)? {
            total += copy_range(infd, outfd, extent.start, extent.end, opts, updater)?;
        }
        Ok(total)
    } else {
        copy_sequential(infd, outfd, len, opts, updater)
    }
}

/// Copy a single regular file including its metadata.
pub fn copy_file(from: &Path, to: &Path, opts: &Opts, updater: &mut BatchUpdater) -> Result<u64> {
    let (infd, outfd, len) = open_pair(from, to, opts)?;
    let result = copy_file_data(&infd, &outfd, len, opts, updater);
    fsops::copy_metadata(&infd, &outfd, opts)?;
    if opts.fsync {
        fsops::sync(&outfd)?;
    }
    result
}

// ---------------------------------------------------------------------
// Tree walking
// ---------------------------------------------------------------------

fn target_base(source: &Path, dest: &Path, opts: &Opts) -> PathBuf {
    if dest.is_dir() && !opts.no_target_directory {
        match source.components().last() {
            Some(c) => dest.join(c.as_os_str()),
            None => dest.to_path_buf(),
        }
    } else {
        dest.to_path_buf()
    }
}

fn is_ignored(entry: &DirEntry, gitignore: &Option<Gitignore>) -> bool {
    match gitignore {
        Some(gi) => gi
            .matched(entry.path(), entry.file_type().is_dir())
            .is_ignore(),
        None => false,
    }
}

fn walk_source(
    source: &Path,
    dest: &Path,
    opts: &Opts,
    ops: &Sender<Operation>,
    stats: &StatSender,
) -> Result<()> {
    let target = target_base(source, dest, opts);
    debug!(target: LOG_TARGET, "Target base is {:?}", target);

    let gitignore = if opts.gitignore {
        let gi_path = source.join(".gitignore");
        info!("Using .gitignore file {:?}", gi_path);
        let (gi, _err) = Gitignore::new(&gi_path);
        Some(gi)
    } else {
        None
    };

    let walker = WalkDir::new(source)
        .into_iter()
        .filter_entry(move |e| !is_ignored(e, &gitignore));

    for entry in walker {
        debug!(target: LOG_TARGET, "Got tree entry {:?}", entry);
        let entry = entry?;
        let path = entry.path();

        let (from, meta) = if opts.dereference {
            let real = fs::canonicalize(path)?;
            debug!(target: LOG_TARGET, "Dereferencing {:?} into {:?}", path, real);
            let meta = fs::metadata(&real)?;
            (real, meta)
        } else {
            (path.to_path_buf(), fs::symlink_metadata(path)?)
        };

        let to = if entry.depth() == 0 {
            target.clone()
        } else {
            target.join(path.strip_prefix(source)?)
        };

        if opts.no_clobber && to.exists() {
            let err = XcpError::DestinationExists(
                "Destination file exists and --no-clobber is set.",
                to.display().to_string(),
            );
            let msg = XcpError::DestinationExists(
                "Destination file exists and --no-clobber is set.",
                to.display().to_string(),
            );
            stats.send(StatusUpdate::Error(err))?;
            return Err(msg);
        }

        let ftype = meta.file_type();
        if ftype.is_file() {
            debug!(target: LOG_TARGET, "Send copy operation {:?} to {:?}", from, to);
            stats.send(StatusUpdate::Size(meta.len()))?;
            ops.send(Operation::Copy(from, to))?;
        } else if ftype.is_dir() {
            debug!(target: LOG_TARGET, "Creating target directory {:?}", to);
            if let Err(e) = fs::create_dir(&to) {
                if !(e.kind() == std::io::ErrorKind::AlreadyExists && to.is_dir()) {
                    error!("Error creating target directory: {}", e);
                    return Err(XcpError::CopyError(format!(
                        "Error creating target directory: {}",
                        e
                    )));
                }
            }
        } else if ftype.is_symlink() {
            let link_target = fs::read_link(&from)?;
            debug!(target: LOG_TARGET, "Send symlink operation {:?} to {:?}", link_target, to);
            ops.send(Operation::Link(link_target, to))?;
        } else {
            debug!(target: LOG_TARGET, "Special file found: {:?} to {:?}", from, to);
            ops.send(Operation::Special(from, to))?;
        }
    }

    Ok(())
}

/// Walk all sources, emitting operations for the driver.
pub fn tree_walker(
    sources: Vec<PathBuf>,
    dest: PathBuf,
    opts: Opts,
    ops: Sender<Operation>,
    stats: StatSender,
) -> Result<()> {
    debug!(target: LOG_TARGET, "Starting walk worker {:?}", std::thread::current().id());
    for source in &sources {
        walk_source(source, &dest, &opts, &ops, &stats)?;
    }
    debug!(target: LOG_TARGET, "Walk-worker finished: {:?}", std::thread::current().id());
    Ok(())
}
