    }
    debug!(target: LOG_TARGET, "Attempting reflink from {:?}->{:?}", infd, outfd);
    if fsops::reflink(infd, outfd)? {
        debug!(target: LOG_TARGET, "Reflink {:?} succeeded", outfd);
        return Ok(true);
    }
    if opts.reflink == Reflink::Always {
        return Err(XcpError::ReflinkFailed(format!("{:?}->{:?}", infd, outfd)));
    }
    debug!(target: LOG_TARGET, "Failed to reflink, falling back to copy");
    Ok(false)
}

fn copy_range(
    infd: &File,
    outfd: &File,
    start: u64,
    end: u64,
    opts: &Opts,
    updater: &mut BatchUpdater,
) -> Result<u64> {
    let mut total = 0u64;
    let mut off = start;
    while off < end {
        let chunk = (end - off).min(opts.block_size);
        let n = fsops::copy_file_offset(infd, outfd, chunk, off)?;
        if n == 0 {
            break;
        }
        updater.update(n)?;
        off += n;
        total += n;
    }
    Ok(total)
}

fn copy_sequential(
    infd: &File,
    outfd: &File,
    len: u64,
    opts: &Opts,
    updater: &mut BatchUpdater,
) -> Result<u64> {
    let mut total = 0u64;
    while total < len {
        let chunk = (len - total).min(opts.block_size);
        let n = fsops::copy_file_bytes(infd, outfd, chunk)?;
        if n == 0 {
            break;
        }
        updater.update(n)?;
        total += n;
    }
    Ok(total)
}

/// Copy the data of a file, reflinking where possible and preserving
/// sparse regions.
pub fn copy_file_data(
    infd: &File,
    outfd: &File,
    len: u64,
    opts: &Opts,
    updater: &mut BatchUpdater,
) -> Result<u64> {
    if try_reflink(infd, outfd, opts)? {
        return Ok(len);
    }
    if fsops::probably_sparse(infd)? {
        let mut total = 0u64;
        for extent in fsops::map_extents(infd)? {
            total += copy_range(infd, outfd, extent.start, extent.end, opts, updater)?;
        }
        Ok(total)
    } else {
        copy_sequential(infd, outfd, len, opts, updater)
    }
}

/// Copy a single regular file including its metadata.
pub fn copy_file(from: &Path, to: &Path, opts: &Opts, updater: &mut BatchUpdater) -> Result<u64> {
    let (infd, outfd, len) = open_pair(from, to, opts)?;
    let result = copy_file_data(&infd, &outfd, len, opts, updater);
    fsops::copy_metadata(&infd, &outfd, opts)?;
    if opts.fsync {
        fsops::sync(&outfd)?;
    }
    result
}

// ---------------------------------------------------------------------
// Tree walking
// ---------------------------------------------------------------------

fn target_base(source: &Path, dest: &Path, opts: &Opts) -> PathBuf {
    if dest.is_dir() && !opts.no_target_directory {
        match source.components().last() {
            Some(c) => dest.join(c.as_os_str()),
            None => dest.to_path_buf(),
        }
    } else {
        dest.to_path_buf()
    }
}

fn is_ignored(entry: &DirEntry, gitignore: &Option<Gitignore>) -> bool {
    match gitignore {
        Some(gi) => gi
            .matched(entry.path(), entry.file_type().is_dir())
            .is_ignore(),
        None => false,
    }
}

fn walk_source(
    source: &Path,
    dest: &Path,
    opts: &Opts,
    ops: &Sender<Operation>,
    stats: &StatSender,
) -> Result<()> {
    let target = target_base(source, dest, opts);
    debug!(target: LOG_TARGET, "Target base is {:?}", target);

    let gitignore = if opts.gitignore {
        let gi_path = source.join(".gitignore");
        info!("Using .gitignore file {:?}", gi_path);
        let (gi, _err) = Gitignore::new(&gi_path);
        Some(gi)
    } else {
        None
    };

    let walker = WalkDir::new(source)
        .into_iter()
        .filter_entry(move |e| !is_ignored(e, &gitignore));

    for entry in walker {
        debug!(target: LOG_TARGET, "Got tree entry {:?}", entry);
        let entry = entry?;
        let path = entry.path();

        let (from, meta) = if opts.dereference {
            let real = fs::canonicalize(path)?;
            debug!(target: LOG_TARGET, "Dereferencing {:?} into {:?}", path, real);
            let meta = fs::metadata(&real)?;
            (real, meta)
        } else {
            (path.to_path_buf(), fs::symlink_metadata(path)?)
        };

        let to = if entry.depth() == 0 {
            target.clone()
        } else {
            target.join(path.strip_prefix(source)?)
        };

        if opts.no_clobber && to.exists() {
            let err = XcpError::DestinationExists(
                "Destination file exists and --no-clobber is set.",
                to.display().to_string(),
            );
            let msg = XcpError::DestinationExists(
                "Destination file exists and --no-clobber is set.",
                to.display().to_string(),
            );
            stats.send(StatusUpdate::Error(err))?;
            return Err(msg);
        }

        let ftype = meta.file_type();
        if ftype.is_file() {
            debug!(target: LOG_TARGET, "Send copy operation {:?} to {:?}", from, to);
            stats.send(StatusUpdate::Size(meta.len()))?;
            ops.send(Operation::Copy(from, to))?;
        } else if ftype.is_dir() {
            debug!(target: LOG_TARGET, "Creating target directory {:?}", to);
            if let Err(e) = fs::create_dir(&to) {
                if !(e.kind() == std::io::ErrorKind::AlreadyExists && to.is_dir()) {
                    error!("Error creating target directory: {}", e);
                    return Err(XcpError::CopyError(format!(
                        "Error creating target directory: {}",
                        e
                    )));
                }
            }
        } else if ftype.is_symlink() {
            let link_target = fs::read_link(&from)?;
            debug!(target: LOG_TARGET, "Send symlink operation {:?} to {:?}", link_target, to);
            ops.send(Operation::Link(link_target, to))?;
        } else {
            debug!(target: LOG_TARGET, "Special file found: {:?} to {:?}", from, to);
            ops.send(Operation::Special(from, to))?;
        }
    }

    Ok(())
}

/// Walk all sources, emitting operations for the driver.
pub fn tree_walker(
    sources: Vec<PathBuf>,
    dest: PathBuf,
    opts: Opts,
    ops: Sender<Operation>,
    stats: StatSender,
) -> Result<()> {
    debug!(target: LOG_TARGET, "Starting walk worker {:?}", std::thread::current().id());
    for source in &sources {
        walk_source(source, &dest, &opts, &ops, &stats)?;
    }
    debug!(target: LOG_TARGET, "Walk-worker finished: {:?}", std::thread::current().id());
    Ok(())
}
