//! Copy drivers. A driver takes operations from the tree walker and
//! performs them, reporting progress back to the main thread.

pub mod parblock;
pub mod parfile;

use std::path::PathBuf;
use std::thread::JoinHandle;

use crate::errors::{Result, XcpError};
use crate::operations::StatSender;
use crate::options::{Driver, Opts};

/// Handles to the threads performing a copy; `join` waits for them all
/// and returns the first error encountered.
pub struct CopyHandle {
    walker: JoinHandle<Result<()>>,
    workers: Vec<JoinHandle<Result<()>>>,
    worker_panic_msg: &'static str,
}

impl CopyHandle {
    pub fn join(self) -> Result<()> {
        let walker_result = self
            .walker
            .join()
            .map_err(|_| XcpError::CopyError("Error during tree walk".to_string()))?;
        walker_result?;
        for w in self.workers {
            let r = w
                .join()
                .map_err(|_| XcpError::CopyError(self.worker_panic_msg.to_string()))?;
            r?;
        }
        Ok(())
    }
}

/// Start the configured driver on the given sources.
pub fn start(opts: Opts, sources: Vec<PathBuf>, dest: PathBuf, stats: StatSender) -> CopyHandle {
    match opts.driver {
        Driver::ParFile => parfile::start(opts, sources, dest, stats),
        Driver::ParBlock => parblock::start(opts, sources, dest, stats),
    }
}
