//! File-parallel driver: a pool of workers each copying whole files.

use std::path::PathBuf;
use std::thread;

use crossbeam_channel::{unbounded, Receiver};
use log::{debug, error, info};

use super::CopyHandle;
use crate::errors::{Result, XcpError};
use crate::fsops;
use crate::operations::{copy_file, tree_walker, BatchUpdater, Operation, StatSender, StatusUpdate};
use crate::options::Opts;

const LOG_TARGET: &str = "libxcp::drivers::parfile";

fn copy_worker(ops: Receiver<Operation>, stats: StatSender, opts: Opts) -> Result<()> {
    let id = thread::current().id();
    debug!(target: LOG_TARGET, "Starting copy worker {:?}", id);
    let mut updater = BatchUpdater::new(stats.clone(), opts.block_size);

    for op in ops.iter() {
        debug!(target: LOG_TARGET, "Received operation {:?}", op);
        match op {
            Operation::Copy(from, to) => {
                info!("Worker[{:?}]: Copy {:?} -> {:?}", id, from, to);
                if let Err(e) = copy_file(&from, &to, &opts, &mut updater) {
                    error!("Error copying: {:?} -> {:?}; aborting.", from, to);
                    stats.send(StatusUpdate::Error(XcpError::CopyError(e.to_string())))?;
                    return Err(e);
                }
            }
            Operation::Link(from, to) => {
                info!("Worker[{:?}]: Symlink {:?} -> {:?}", id, from, to);
                fsops::symlink(&from, &to)?;
            }
            Operation::Special(from, to) => {
                info!("Worker[{:?}]: Special file {:?} -> {:?}", id, from, to);
                fsops::copy_node(&from, &to)?;
            }
        }
    }

    debug!(target: LOG_TARGET, "Copy worker {:?} shutting down", id);
    Ok(())
}

pub fn start(opts: Opts, sources: Vec<PathBuf>, dest: PathBuf, stats: StatSender) -> CopyHandle {
    let (op_tx, op_rx) = unbounded::<Operation>();

    let walker = {
        let opts = opts.clone();
        let stats = stats.clone();
        thread::spawn(move || tree_walker(sources, dest, opts, op_tx, stats))
    };

    let nworkers = opts.num_workers();
    let mut workers = Vec::with_capacity(nworkers);
    for _ in 0..nworkers {
        let rx = op_rx.clone();
        let stats = stats.clone();
        let opts = opts.clone();
        workers.push(thread::spawn(move || copy_worker(rx, stats, opts)));
    }

    CopyHandle {
        walker,
        workers,
        worker_panic_msg: "Error during copy operation",
    }
}
