    };

    let nworkers = opts.num_workers();
    let mut workers = Vec::with_capacity(nworkers);
    for _ in 0..nworkers {
        let rx = op_rx.clone();
        let stats = stats.clone();
        let opts = opts.clone();
        workers.push(thread::spawn(move || copy_worker(rx, stats, opts)));
    }

    CopyHandle {
        walker,
        workers,
        worker_panic_msg: "Error during copy operation",
    }
}
