//! Block-parallel driver: files are split into blocks which are copied
//! concurrently by a thread pool.

use std::fs::File;
use std::path::PathBuf;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::thread;

use crossbeam_channel::{unbounded, Receiver};
use log::{debug, error, info};

use super::CopyHandle;
use crate::errors::{Result, XcpError};
use crate::fsops;
use crate::operations::{
    open_pair, tree_walker, try_reflink, BatchUpdater, Operation, StatSender, StatusUpdate,
};
use crate::options::Opts;
use crate::threadpool::ThreadPool;

/// Shared state for the blocks of one file.
struct FileJob {
    infd: File,
    outfd: File,
    opts: Opts,
    stats: StatSender,
    remaining: AtomicUsize,
}

impl FileJob {
    fn finish_metadata(&self) -> Result<()> {
        fsops::copy_metadata(&self.infd, &self.outfd, &self.opts)?;
        if self.opts.fsync {
            fsops::sync(&self.outfd)?;
        }
        Ok(())
    }

    fn report(&self, e: XcpError) {
        let _ = self
            .stats
            .send(StatusUpdate::Error(XcpError::CopyError(e.to_string())));
    }
}

fn copy_block(job: &FileJob, off: u64, len: u64) -> Result<()> {
    let mut updater = BatchUpdater::new(job.stats.clone(), job.opts.block_size);
    let mut done = 0u64;
    while done < len {
        let n = fsops::copy_file_offset(&job.infd, &job.outfd, len - done, off + done)?;
        if n == 0 {
            break;
        }
        updater.update(n)?;
        done += n;
    }
    Ok(())
}

fn block_job(job: Arc<FileJob>, off: u64, len: u64) {
    if let Err(e) = copy_block(&job, off, len) {
        error!("Error copying: aborting.");
        job.report(e);
    }
    if job.remaining.fetch_sub(1, Ordering::SeqCst) == 1 {
        if let Err(e) = job.finish_metadata() {
            job.report(e);
        }
    }
}

fn queue_file(
    pool: &mut Option<ThreadPool>,
    from: &PathBuf,
    to: &PathBuf,
    opts: &Opts,
    stats: &StatSender,
) -> Result<()> {
    let (infd, outfd, len) = open_pair(from, to, opts)?;

    let reflinked = try_reflink(&infd, &outfd, opts);
    match reflinked {
        Ok(true) => {
            info!("Reflinked, skipping rest of copy");
            fsops::copy_metadata(&infd, &outfd, opts)?;
            if opts.fsync {
                fsops::sync(&outfd)?;
            }
            return Ok(());
        }
        Ok(false) => {}
        Err(e) => {
            fsops::copy_metadata(&infd, &outfd, opts)?;
            return Err(e);
        }
    }

    let bsize = opts.block_size;
    let mut nblocks = len / bsize;
    if len % bsize > 0 {
        nblocks += 1;
    }

    let job = Arc::new(FileJob {
        infd,
        outfd,
        opts: opts.clone(),
        stats: stats.clone(),
        remaining: AtomicUsize::new(nblocks as usize),
    });

    if nblocks == 0 {
        job.finish_metadata()?;
        return Ok(());
    }

    let pool = pool.get_or_insert_with(|| ThreadPool::new(opts.num_workers()));
    for i in 0..nblocks {
        let off = i * bsize;
        let blen = bsize.min(len - off);
        let job = job.clone();
        pool.execute(move || block_job(job, off, blen))
            .map_err(|_| XcpError::CopyError("Error dispatching copy operation".to_string()))?;
    }
    Ok(())
}

fn dispatcher(ops: Receiver<Operation>, stats: StatSender, opts: Opts) -> Result<()> {
    let id = thread::current().id();
    let mut pool: Option<ThreadPool> = None;

    for op in ops.iter() {
        debug!(target: "libxcp::drivers::parblock", "Received operation {:?}", op);
        match op {
            Operation::Copy(from, to) => {
                info!("Dispatch[{:?}]: Copy {:?} -> {:?}", id, from, to);
                if let Err(e) = queue_file(&mut pool, &from, &to, &opts, &stats) {
                    stats.send(StatusUpdate::Error(XcpError::CopyError(e.to_string())))?;
                    return Err(e);
                }
            }
            Operation::Link(from, to) => {
                info!("Dispatch[{:?}]: Symlink {:?} -> {:?}", id, from, to);
                fsops::symlink(&from, &to)?;
            }
            Operation::Special(from, to) => {
                info!("Dispatch[{:?}]: Special file {:?} -> {:?}", id, from, to);
                fsops::copy_node(&from, &to)?;
            }
        }
    }

    info!("Queuing complete");
    if let Some(mut p) = pool.take() {
        p.join()
            .map_err(|_| XcpError::CopyError("Error during copy operation".to_string()))?;
    }
    info!("Pool complete");
    Ok(())
}

pub fn start(opts: Opts, sources: Vec<PathBuf>, dest: PathBuf, stats: StatSender) -> CopyHandle {
    let (op_tx, op_rx) = unbounded::<Operation>();

    let dispatch = {
        let opts = opts.clone();
        let stats = stats.clone();
        thread::spawn(move || dispatcher(op_rx, stats, opts))
    };

    let walker = thread::spawn(move || tree_walker(sources, dest, opts, op_tx, stats));

    CopyHandle {
        walker,
        workers: vec![dispatch],
        worker_panic_msg: "Error dispatching copy operation",
    }
}
