use crate::operations::StatusUpdate;
use crate::options::{Opts, Reflink};
use crate::progress::{Layout, ProgressBar};

/// Expand the source list, applying glob patterns if requested.
fn expand_sources(opts: &Opts, sources: Vec<PathBuf>) -> Result<Vec<PathBuf>> {
    if !opts.glob {
        return Ok(sources);
    }
    let mut expanded = Vec::new();
    for pattern in sources {
        let pat = pattern.to_string_lossy();
        for entry in glob::glob(&pat).map_err(XcpError::from)? {
            expanded.push(entry.map_err(XcpError::from)?);
        }
    }
    Ok(expanded)
}

fn run(opts: Opts) -> Result<()> {
    if opts.force && opts.no_clobber {
        return Err(XcpError::InvalidArguments(
            "--force and --noclobber cannot be set at the same time.".to_string(),
        )
        .into());
    }

    let mut paths = opts.paths.clone();
    let (sources, dest) = match &opts.target_directory {
        Some(td) => (paths, td.clone()),
        None => {
            if paths.is_empty() {
                return Err(
                    XcpError::InvalidArguments("Insufficient arguments".to_string()).into(),
                );
            }
            let dest = paths.pop().expect("non-empty");
            (paths, dest)
        }
    };

    let sources = expand_sources(&opts, sources)?;
    if sources.is_empty() {
        return Err(XcpError::InvalidSource("No source files found.").into());
    }

    if sources.len() > 1 && !dest.is_dir() {
        return Err(XcpError::InvalidDestination(
            "Multiple sources and destination is not a directory.",
        )
        .into());
    }

    for source in &sources {
        if !source.exists() {
            return Err(XcpError::InvalidSource("Source does not exist.").into());
        }
        if source.is_dir() && !opts.recursive {
            return Err(XcpError::InvalidSource(
                "Source is directory and --recursive not specified.",
            )
            .into());
        }
        if *source == dest {
            return Err(XcpError::InvalidSource("Cannot copy a directory into itself").into());
        }
        if source.is_dir() && dest.is_file() {
            return Err(XcpError::InvalidDestination("Cannot copy a directory to a file.").into());
        }
    }

    let layout = Layout::detect();
    let mut pb = ProgressBar::new(!opts.no_progress, layout);

    let (stat_tx, stat_rx) = unbounded::<StatusUpdate>();

    for source in &sources {
        info!("Copying source {:?} to {:?}", source, dest);
    }

    let handle = drivers::start(opts, sources, dest, stat_tx);

    for update in stat_rx.iter() {
        match update {
            StatusUpdate::Copied(bytes) => pb.inc(bytes),
            StatusUpdate::Size(bytes) => pb.inc_length(bytes),
            StatusUpdate::Error(e) => {
                error!("Received error: {}", e);
                return Err(e.into());
            }
        }
    }

    handle.join()?;

    info!("Copy complete");
    pb.finish();

    Ok(())
}

fn main() -> Result<()> {
    let opts = options::parse_args();

    let level = match opts.verbose {
        0 => LevelFilter::Warn,
        1 => LevelFilter::Info,
        2 => LevelFilter::Debug,
        _ => LevelFilter::Trace,
    };
    logger::init(level);

    // Reserve a thread id so worker numbering is stable.
    let _ = std::thread::spawn(|| {}).join();

    if opts.reflink == Reflink::Never {
        warn!("--reflink=never is selected, however the Linux kernel may override this.");
    }

    run(opts)
}
