const FALLBACK_BUF: usize = 1024 * 1024;

/// Userspace copy for filesystems/kernels where `copy_file_range` is
/// not available between the two files. Copies at most `bytes`.
fn copy_bytes_userspace(infd: &File, outfd: &File, bytes: u64, off: Option<u64>) -> io::Result<u64> {
    use std::os::unix::fs::FileExt;
    use std::io::{Read, Write};
    let mut buf = vec![0u8; (bytes as usize).min(FALLBACK_BUF)];
    let mut done = 0u64;
    while done < bytes {
        let want = ((bytes - done) as usize).min(buf.len());
        let n = match off {
            Some(o) => infd.read_at(&mut buf[..want], o + done)?,
            None => (&*infd).read(&mut buf[..want])?,
        };
        if n == 0 {
            break;
        }
        match off {
            Some(o) => outfd.write_all_at(&buf[..n], o + done)?,
            None => (&*outfd).write_all(&buf[..n])?,
        }
        done += n as u64;
    }
    Ok(done)
}

