/// of `outfd` using `copy_file_range`, falling back to a userspace copy
/// where the kernel cannot do it.
pub fn copy_file_bytes(infd: &File, outfd: &File, bytes: u64) -> Result<u64> {
    let rc = unsafe {
        libc::syscall(
            libc::SYS_copy_file_range,
            infd.as_raw_fd(),
            std::ptr::null_mut::<libc::loff_t>(),
            outfd.as_raw_fd(),
            std::ptr::null_mut::<libc::loff_t>(),
            bytes as usize,
            0u32,
        )
    };
    match cvt(rc as i64) {
        Ok(n) => Ok(n as u64),
        Err(e) if needs_fallback(&e) => Ok(copy_bytes_userspace(infd, outfd, bytes, None)?),
        Err(e) => Err(e.into()),
    }
}

