    let mut in_off = off as libc::loff_t;
    let mut out_off = off as libc::loff_t;
    let rc = unsafe {
        libc::syscall(
            libc::SYS_copy_file_range,
            infd.as_raw_fd(),
            &mut in_off as *mut libc::loff_t,
            outfd.as_raw_fd(),
            &mut out_off as *mut libc::loff_t,
            bytes as usize,
            0u32,
        )
    };
    match cvt(rc as i64) {
        Ok(n) => Ok(n as u64),
        Err(e) if needs_fallback(&e) => Ok(copy_bytes_userspace(infd, outfd, bytes, Some(off))?),
        Err(e) => Err(e.into()),
    }
}

