//! Block-parallel driver: files are split into blocks which are copied
//! concurrently by a set of worker threads.

use std::fs::File;
use std::path::PathBuf;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::thread::{self, JoinHandle};

use crossbeam_channel::{unbounded, Receiver, Sender};
use log::{error, info};

use crate::errors::{Result, XcpError};
use crate::fsops;
use crate::operations::{
    finish_file, open_pair, tree_walker, try_reflink, BatchUpdater, FilePair, Operation,
    StatSender, StatusUpdate,
};
use crate::options::Opts;

/// Shared state for the blocks of one file.
struct FileJob {
    infd: File,
    outfd: File,
    opts: Opts,
    stats: StatSender,
    remaining: AtomicUsize,
}

impl FileJob {
    fn report(&self, e: XcpError) {
        let _ = self
            .stats
            .send(StatusUpdate::Error(XcpError::CopyError(e.to_string())));
    }
}

/// One block of a file to copy.
struct Block {
    job: Arc<FileJob>,
    off: u64,
    len: u64,
}

fn copy_block(block: &Block, updater: &mut BatchUpdater) -> Result<()> {
    let job = &block.job;
    let mut done = 0u64;
    while done < block.len {
        let n = fsops::copy_file_offset(
            &job.infd,
            &job.outfd,
            block.len - done,
            block.off + done,
        )?;
        updater.update(n)?;
        if n == 0 {
            break;
        }
        done += n;
    }
    Ok(())
}

fn block_worker(blocks: Receiver<Block>, stats: StatSender, opts: Opts) {
    let mut updater = BatchUpdater::new(stats, opts.block_size);
    for block in blocks.iter() {
        if let Err(e) = copy_block(&block, &mut updater) {
            block.job.report(e);
            error!("Error copying: aborting.");
        }
        let job = &block.job;
        if job.remaining.fetch_sub(1, Ordering::SeqCst) == 1 {
            if let Err(e) = finish_file(&job.infd, &job.outfd, &job.opts) {
                job.report(e);
            }
        }
    }
}

/// A fixed set of threads consuming blocks from a queue.
struct BlockPool {
    sender: Option<Sender<Block>>,
    workers: Vec<JoinHandle<()>>,
}

impl BlockPool {
    fn new(size: usize, stats: &StatSender, opts: &Opts) -> BlockPool {
        let (tx, rx) = unbounded::<Block>();
        let workers = (0..size.max(1))
            .map(|_| {
                let rx = rx.clone();
                let stats = stats.clone();
                let opts = opts.clone();
                thread::spawn(move || block_worker(rx, stats, opts))
            })
            .collect();
        BlockPool {
            sender: Some(tx),
            workers,
        }
    }

    fn execute(&self, block: Block) -> Result<()> {
        match &self.sender {
            Some(tx) => tx
                .send(block)
                .map_err(|_| XcpError::CopyError("Error dispatching copy operation".to_string())),
            None => Err(XcpError::CopyError("Error dispatching copy operation".to_string())),
        }
    }

    fn join(&mut self) -> Result<()> {
        self.sender.take();
        let mut failed = false;
        for h in self.workers.drain(..) {
            if h.join().is_err() {
                failed = true;
            }
        }
        if failed {
            Err(XcpError::CopyError("Error during copy operation".to_string()))
        } else {
            Ok(())
        }
    }
}

fn queue_file(
    pool: &BlockPool,
    from: &PathBuf,
    to: &PathBuf,
    opts: &Opts,
    stats: &StatSender,
) -> Result<()> {
    let FilePair {
        infd,
        outfd,
        len,
        sparse: _,
    } = open_pair(from, to, opts)?;

    match try_reflink(&infd, &outfd, opts) {
        Ok(true) => {
            info!("Reflinked, skipping rest of copy");
            finish_file(&infd, &outfd, opts)?;
            return Ok(());
        }
        Ok(false) => {}
        Err(e) => {
            fsops::copy_metadata(&infd, &outfd, opts)?;
            return Err(e);
        }
    }

    let bsize = opts.block_size;
    let mut nblocks = len / bsize;
    if len % bsize > 0 {
        nblocks += 1;
    }

    let job = Arc::new(FileJob {
        infd,
        outfd,
        opts: opts.clone(),
        stats: stats.clone(),
        remaining: AtomicUsize::new(nblocks as usize),
    });

    if nblocks == 0 {
        finish_file(&job.infd, &job.outfd, opts)?;
        return Ok(());
    }

    for i in 0..nblocks {
        let off = i * bsize;
        let blen = bsize.min(len - off);
        pool.execute(Block {
            job: job.clone(),
            off,
            len: blen,
        })?;
    }
    Ok(())
}

fn dispatcher(
    ops: Receiver<Operation>,
    stats: StatSender,
    opts: Opts,
    go: Receiver<()>,
) -> Result<()> {
    let id = thread::current().id();

    // Wait until the walker has been started before creating the pool so
    // that thread creation order is stable.
    let _ = go.recv();
    let mut pool = BlockPool::new(opts.num_workers(), &stats, &opts);

    for op in ops.iter() {
        match op {
            Operation::Copy(from, to) => {
                info!("Dispatch[{:?}]: Copy {:?} -> {:?}", id, from, to);
                if let Err(e) = queue_file(&pool, &from, &to, &opts, &stats) {
                    stats.send(StatusUpdate::Error(XcpError::CopyError(e.to_string())))?;
                    error!("Dispatcher: Error copying {:?} -> {:?}.", from, to);
                    return Err(e);
                }
            }
            Operation::Link(from, to) => {
                info!("Dispatch[{:?}]: Symlink {:?} -> {:?}", id, from, to);
                fsops::symlink(&from, &to)?;
            }
            Operation::Special(from, to) => {
                info!("Dispatch[{:?}]: Special file {:?} -> {:?}", id, from, to);
                fsops::copy_node(&from, &to)?;
            }
        }
    }

    info!("Queuing complete");
    pool.join()?;
    info!("Pool complete");
    Ok(())
}

/// Run the block-parallel copy; returns when all work is complete.
pub fn copy(opts: Opts, sources: Vec<PathBuf>, dest: PathBuf, stats: StatSender) -> Result<()> {
    let (op_tx, op_rx) = unbounded::<Operation>();
    let (go_tx, go_rx) = unbounded::<()>();

    let dispatch = {
        let opts = opts.clone();
        let stats = stats.clone();
        thread::spawn(move || dispatcher(op_rx, stats, opts, go_rx))
    };

    let walker = thread::spawn(move || tree_walker(sources, dest, opts, op_tx, stats));
    let _ = go_tx.send(());

    walker
        .join()
        .map_err(|_| XcpError::CopyError("Error during tree walk".to_string()))??;

    dispatch
        .join()
        .map_err(|_| XcpError::CopyError("Error dispatching copy operation".to_string()))??;
    Ok(())
}
